function getWithTimeout(key, timeout, cb) {
  let timer;
  const timeoutError = new Error('timeout');

  const timeoutCallback = function() {
    cb(timeoutError);
  };

  const dataCallback = function(err, data) {
    clearTimeout(timer);
    cb(err, data);
  };

  timer = setTimeout(timeoutCallback, timeout);
  client.get(key, dataCallback);
}
